graphql-context-auth-guard.promptSeed:
Implement a higher-order resolver guard that enforces authentication and role-based authorization from the GraphQL `context`:

## Description

```ts
type GraphQLResolver<TSource = any, TArgs = any, TContext = any, TResult = any> = (
  parent: TSource,
  args: TArgs,
  context: TContext,
  info: any
) => TResult;

interface UserPayload {
  id: string;
  roles?: string[];
}

interface AuthContext {
  user?: UserPayload | null;
  [key: string]: any;
}
```

### `withAuth<TSource = any, TArgs = any, TResult = any>(resolver: GraphQLResolver<TSource, TArgs, AuthContext, TResult>, requiredRoles?: string[]): GraphQLResolver<TSource, TArgs, AuthContext, TResult>`

- **Authentication Guard**:
  - Inspects `context.user`.
  - If `context.user` is absent or `null`, throws an `Error('UNAUTHENTICATED')`.
- **Role-Based Authorization (`requiredRoles`)**:
  - If `requiredRoles` is provided and non-empty, checks whether `context.user.roles` contains at least one of the required roles.
  - If the user has no matching roles (or `context.user.roles` is undefined/empty), throws an `Error('FORBIDDEN')`.
  - If `requiredRoles` is omitted or empty, any authenticated user passes.
- **Resolver Execution**:
  - When authorized, calls and returns `resolver(parent, args, context, info)`.
  - Seamlessly handles both synchronous return values and asynchronous promises.

graphql-context-auth-guard.testHarness:
await $test.run("Allows authenticated user without role restriction and passes resolver arguments through", async () => {
  const sleep = $test.sleep;
  const guard = withAuth((p, a, c, i) => ({ p, a, userId: c.user.id, i }));
  return (guard('parentVal', { key: 'val' }, { user: { id: 'u1' } }, 'infoVal'));
}, () => ({ p: 'parentVal', a: { key: 'val' }, userId: 'u1', i: 'infoVal' }));

await $test.run("Throws UNAUTHENTICATED when context.user is missing or null", async () => {
  const sleep = $test.sleep;
  const guard = withAuth(() => 'ok');
  const err1 = (() => { try { guard(null, {}, {}); return 'no error'; } catch (e) { return e.message; } })();
  const err2 = (() => { try { guard(null, {}, { user: null }); return 'no error'; } catch (e) { return e.message; } })();
  return ([err1, err2]);
}, () => (['UNAUTHENTICATED', 'UNAUTHENTICATED']));

await $test.run("Allows access when user possesses at least one required role", async () => {
  const sleep = $test.sleep;
  const guard = withAuth(() => 'authorized', ['admin', 'editor']);
  return (guard(null, {}, { user: { id: 'u1', roles: ['user', 'editor'] } }));
}, () => ('authorized'));

await $test.run("Throws FORBIDDEN when user lacks any required role or has empty roles", async () => {
  const sleep = $test.sleep;
  const guard = withAuth(() => 'authorized', ['admin', 'superadmin']);
  const err1 = (() => { try { guard(null, {}, { user: { id: 'u1', roles: ['guest'] } }); return 'no error'; } catch (e) { return e.message; } })();
  const err2 = (() => { try { guard(null, {}, { user: { id: 'u2', roles: [] } }); return 'no error'; } catch (e) { return e.message; } })();
  const err3 = (() => { try { guard(null, {}, { user: { id: 'u3' } }); return 'no error'; } catch (e) { return e.message; } })();
  return ([err1, err2, err3]);
}, () => (['FORBIDDEN', 'FORBIDDEN', 'FORBIDDEN']));

await $test.run("Supports asynchronous resolvers returning a promise", async () => {
  const sleep = $test.sleep;
  const guard = withAuth(async (p, a) => a.count * 2);
  return (await guard(null, { count: 21 }, { user: { id: 'u1' } }));
}, () => (42));

graphql-context-auth-guard.referenceSolution:
function withAuth(resolver, requiredRoles = []) {
  return function authenticatedResolver(parent, args, context, info) {
    const user = context?.user;
    if (!user) {
      throw new Error('UNAUTHENTICATED');
    }

    if (Array.isArray(requiredRoles) && requiredRoles.length > 0) {
      const userRoles = Array.isArray(user.roles) ? user.roles : [];
      const hasRole = requiredRoles.some((role) => userRoles.includes(role));
      if (!hasRole) {
        throw new Error('FORBIDDEN');
      }
    }

    return resolver(parent, args, context, info);
  };
}

