graphql-input-object-sanitizer.referenceSolution:
const SCALAR_CHECKS = {
  String: (v) => typeof v === 'string',
  Int: (v) => typeof v === 'number' && Number.isInteger(v),
  Float: (v) => typeof v === 'number' && Number.isFinite(v),
  Boolean: (v) => typeof v === 'boolean',
  ID: (v) => typeof v === 'string' || typeof v === 'number',
};

function sanitizeInput(schema, input) {
  const errors = [];
  const sanitized = {};
  const data = input || {};

  for (const [name, field] of Object.entries(schema || {})) {
    const val = data[name];

    if (val === undefined || val === null) {
      if (field.required) errors.push(`Field '${name}' is required`);
      continue;
    }

    const checker = SCALAR_CHECKS[field.type];
    if (checker && !checker(val)) {
      errors.push(`Field '${name}' must be of type ${field.type}`);
      continue;
    }

    if (Array.isArray(field.enumValues) && !field.enumValues.includes(val)) {
      errors.push(`Field '${name}' must be one of: ${field.enumValues.join(', ')}`);
      continue;
    }

    sanitized[name] = val;
  }

  return errors.length > 0 ? { valid: false, errors } : { valid: true, data: sanitized };
}

graphql-input-object-sanitizer.referenceSolutionTs:
type ScalarType = 'String' | 'Int' | 'Float' | 'Boolean' | 'ID';

interface InputFieldSchema {
  type: ScalarType;
  required?: boolean;
  enumValues?: string[];
}

interface InputSchema {
  [fieldName: string]: InputFieldSchema;
}

interface SanitizedResult<T = any> {
  valid: boolean;
  data?: T;
  errors?: string[];
}

const SCALAR_CHECKS: Record<string, (v: any) => boolean> = {
  String: (v) => typeof v === 'string',
  Int: (v) => typeof v === 'number' && Number.isInteger(v),
  Float: (v) => typeof v === 'number' && Number.isFinite(v),
  Boolean: (v) => typeof v === 'boolean',
  ID: (v) => typeof v === 'string' || typeof v === 'number',
};

function sanitizeInput<T = any>(
  schema: InputSchema,
  input: Record<string, any>
): SanitizedResult<T> {
  const errors: string[] = [];
  const sanitized: Record<string, any> = {};
  const data = input || {};

  for (const [name, field] of Object.entries(schema || {})) {
    const val = data[name];

    if (val === undefined || val === null) {
      if (field.required) errors.push(`Field '${name}' is required`);
      continue;
    }

    const checker = SCALAR_CHECKS[field.type];
    if (checker && !checker(val)) {
      errors.push(`Field '${name}' must be of type ${field.type}`);
      continue;
    }

    if (Array.isArray(field.enumValues) && !field.enumValues.includes(val)) {
      errors.push(`Field '${name}' must be one of: ${field.enumValues.join(', ')}`);
      continue;
    }

    sanitized[name] = val;
  }

  return errors.length > 0 ? { valid: false, errors } : { valid: true, data: sanitized as T };
}

graphql-mini-client.promptSeed:
Write a lightweight GraphQL client request utility using native `fetch`:

## Description

```ts
interface GraphQLResponse<T = any> {
  data?: T;
  errors?: Array<{
    message: string;
    locations?: Array<{ line: number; column: number }>;
    path?: Array<string | number>;
  }>;
}
```

### `fetchGraphQL<T = any>(endpoint: string, query: string, variables?: Record<string, any>, headers?: Record<string, string>): Promise<T>`

- **HTTP Request**:
  - Sends a `POST` request to `endpoint` via `fetch(endpoint, init)`.
  - Sets `'Content-Type': 'application/json'` in the request headers, merging in any custom `headers` passed to the function.
  - JSON-serializes `{ query, variables }` into the request body.
- **HTTP Error Handling**:
  - Inspects `response.ok`. If `response.ok` is false, throws an `Error` whose message includes the HTTP status code (e.g. `500`).
- **GraphQL Error Handling**:
  - Parses the response JSON as a `GraphQLResponse<T>`.
  - If the response payload contains a non-empty `errors` array (`errors.length > 0`), throws an `Error` containing the first error's `message`.
- **Success & Network Failure**:
  - When successful and without errors, resolves with `data` (cast to `T`).
  - Network rejections from `fetch` itself must propagate directly without being swallowed.

graphql-mini-client.testHarness:
const originalFetch = fetch;

try {
  await $test.run("Sends POST request with query and variables in JSON body", async () => {
    let captured = null;
    fetch = async (url, init) => {
      captured = { url, ...init, parsedBody: JSON.parse(init.body) };
      return {
        ok: true,
        status: 200,
        json: async () => ({ data: { viewer: { id: '1', name: 'Alice' } } }),
      };
    };

    const res = await fetchGraphQL('/graphql', 'query { viewer { name } }', { limit: 10 });
    const isPost = captured.method === 'POST';
    const hasContentType = captured.headers['Content-Type'] === 'application/json';
    const matchesQuery = captured.parsedBody.query === 'query { viewer { name } }';
    const matchesVars = captured.parsedBody.variables?.limit === 10;
    return isPost && hasContentType && matchesQuery && matchesVars && res.viewer.name === 'Alice';
  }, () => true);

  await $test.run("Merges custom headers into request", async () => {
    let capturedHeaders = null;
    fetch = async (_url, init) => {
      capturedHeaders = init.headers;
      return {
        ok: true,
        status: 200,
        json: async () => ({ data: { count: 42 } }),
      };
    };

    const res = await fetchGraphQL('/graphql', 'query { count }', undefined, { 'Authorization': 'Bearer token-xyz' });
    const hasAuth = capturedHeaders['Authorization'] === 'Bearer token-xyz';
    const hasContentType = capturedHeaders['Content-Type'] === 'application/json';
    return hasAuth && hasContentType && res.count === 42;
  }, () => true);

  await $test.run("Returns data when errors array is empty", async () => {
    fetch = async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        data: { active: true },
        errors: [],
      }),
    });

    const res = await fetchGraphQL('/graphql', 'query { active }');
    return res.active === true;
  }, () => true);

  fetch = async () => ({
    ok: false,
    status: 500,
    statusText: 'Internal Server Error',
    json: async () => ({}),
  });
  await $test.rejects("Throws an error if response.ok is false", () => fetchGraphQL('/graphql', 'query { viewer { id } }'), '500');

  fetch = async () => ({
    ok: true,
    status: 200,
    json: async () => ({
      errors: [{ message: 'Field "secret" does not exist on type "User"' }],
    }),
  });
  await $test.rejects("Throws an error if GraphQL errors are returned in payload", () => fetchGraphQL('/graphql', 'query { secret }'), 'Field "secret" does not exist');

  fetch = async () => {
    throw new TypeError('Failed to fetch');
  };
  await $test.rejects("Propagates network errors if fetch rejects", () => fetchGraphQL('/graphql', 'query { viewer { id } }'), 'Failed to fetch');
} finally {
  fetch = originalFetch;
}

graphql-mini-client.referenceSolution:
async function fetchGraphQL(endpoint, query, variables, headers = {}) {
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const payload = await response.json();

  if (payload.errors && payload.errors.length > 0) {
    throw new Error(`GraphQL error: ${payload.errors[0].message}`);
  }

  return payload.data;
}

graphql-mini-client.referenceSolutionTs:
interface GraphQLResponse<T = any> {
  data?: T;
  errors?: Array<{
    message: string;
    locations?: Array<{ line: number; column: number }>;
    path?: Array<string | number>;
  }>;
}

async function fetchGraphQL<T = any>(
  endpoint: string,
  query: string,
  variables?: Record<string, any>,
  headers: Record<string, string> = {}
): Promise<T> {
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...headers,
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const payload: GraphQLResponse<T> = await response.json();

  if (payload.errors && payload.errors.length > 0) {
    throw new Error(`GraphQL error: ${payload.errors[0].message}`);
  }

  return payload.data as T;
}

