  const sleep = $test.sleep;
  return (calculateQueryComplexity([{ name: 'posts', args: { limit: 10 }, fields: [{ name: 'comments', args: { first: 5 }, fields: [{ name: 'text' }] }] }], { maxComplexity: 50 }));
}, () => ({ complexity: 61, exceeded: true }));

