  const sleep = $test.sleep;
  const userMap = { Query: { user: () => 'u' }, User: { id: (p) => p.id } };
  const reviewMap = { Query: { reviews: () => [] }, User: { reviews: () => [] } };
  const merged = mergeResolvers(userMap, reviewMap);
  return ([Object.keys(merged.Query).sort(), Object.keys(merged.User).sort()]);
}, () => ([["reviews", "user"], ["id", "reviews"]]));

await $test.run("Throws conflict error when duplicate field is defined on the same type", async () => {
  const sleep = $test.sleep;
  const map1 = { Query: { user: () => 1 } };
  const map2 = { Query: { user: () => 2 } };
  const err = (() => { try { mergeResolvers(map1, map2); return 'no error'; } catch (e) { return e.message; } })();
  return (err);
}, () => ('Conflict: resolver for "Query.user" is defined multiple times'));

await $test.run("Gracefully skips null, undefined, or empty inputs", async () => {
  const sleep = $test.sleep;
  const merged = mergeResolvers(null, { Query: { ping: () => 'pong' } }, undefined, {});
  return (Object.keys(merged.Query));
}, () => (["ping"]));

await $test.run("Preserves custom type resolvers such as __resolveType", async () => {
  const sleep = $test.sleep;
  const map1 = { SearchResult: { __resolveType: () => 'User' } };
  const merged = mergeResolvers(map1);
  return (typeof merged.SearchResult.__resolveType);
}, () => ('function'));

graphql-schema-stitching-merger.referenceSolution:
function mergeResolvers(...resolverMaps) {
  const merged = {};

  for (const map of resolverMaps) {
    if (!map || typeof map !== 'object') continue;

    for (const typeName of Object.keys(map)) {
      const typeFields = map[typeName];
      if (!typeFields || typeof typeFields !== 'object') continue;

      if (!merged[typeName]) {
        merged[typeName] = {};
      }

      for (const fieldName of Object.keys(typeFields)) {
        if (Object.prototype.hasOwnProperty.call(merged[typeName], fieldName)) {
          throw new Error(
            `Conflict: resolver for "${typeName}.${fieldName}" is defined multiple times`
          );
        }
        merged[typeName][fieldName] = typeFields[fieldName];
      }
    }
  }

  return merged;
}

